using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

IChatClient innerClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var tools = new ResearchTools();

ChatClientAgent agent = innerClient.AsAIAgent(
    name: "ResearchAgent",
    description: "An agent that researches a topic by searching the web and taking notes, then produces a summary.",
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information using the web_search tool (perform 2-4 searches with varied queries).
        2. For each useful finding, use the save_note tool to record key facts with source URLs.
        3. After gathering enough information, use the get_notes tool to review all your notes.
        4. Produce a well-structured summary with source citations.
        Be thorough but concise. Always cite your sources.
        """,
    tools: [
        AIFunctionFactory.Create(tools.WebSearch),
        AIFunctionFactory.Create(tools.SaveNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ]);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (MAF)        ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Enter a research topic (or 'quit' to exit): ");

while (Console.ReadLine() is { } topic && !topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(topic))
    {
        Console.Write("\nEnter a research topic (or 'quit' to exit): ");
        continue;
    }

    tools.ClearNotes();
    Console.WriteLine($"\n🔍 Researching: {topic}\n");

    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    var options = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    };

    try
    {
        await foreach (var update in agent.GetStreamingResponseAsync(messages, options))
        {
            Console.Write(update.Text);
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
    }

    Console.WriteLine("\n");
    Console.Write("Enter a research topic (or 'quit' to exit): ");
}

Console.WriteLine("Goodbye!");

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    private readonly List<ResearchNote> _notes = [];

    [Description("Search the web for information on a query. Returns a list of search result titles, snippets, and URLs.")]
    public async Task<string> WebSearch(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            using var response = await s_httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadFromJsonAsync<JsonElement>();

            var results = new List<string>();

            // Abstract/instant answer
            var abstractText = json.TryGetProperty("AbstractText", out var at) ? at.GetString() : null;
            var abstractUrl = json.TryGetProperty("AbstractURL", out var au) ? au.GetString() : null;
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[Summary] {abstractText}\nSource: {abstractUrl}");
            }

            // Related topics
            if (json.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var topic in topics.EnumerateArray().Take(8))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var fu) ? fu.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add($"- {text}\n  URL: {firstUrl}");
                    }
                }
            }

            return results.Count > 0
                ? $"Search results for \"{query}\":\n\n{string.Join("\n\n", results)}"
                : $"No results found for \"{query}\". Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a key fact and its source URL for later reference.")]
    public string SaveNote(
        [Description("The key fact or finding to save")] string fact,
        [Description("The source URL where this fact was found")] string source)
    {
        _notes.Add(new ResearchNote(fact, source));
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes to review before writing the summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet. Use web_search and save_note first.";
        }

        var formatted = _notes.Select((n, i) =>
            $"{i + 1}. {n.Fact}\n   Source: {n.Source}");
        return $"Research notes ({_notes.Count} total):\n\n{string.Join("\n\n", formatted)}";
    }

    public void ClearNotes() => _notes.Clear();

    private sealed record ResearchNote(string Fact, string Source);
}

